from pathlib import Path
path = Path("shop/checkout.py")
source = path.read_text()
start = source.index("def process_order(")
end = source.index("def refund_order(")
new = '''def process_order(
    order: Order,
    customer: Customer,
    inventory: Inventory,
    gateway: PaymentGateway,
    notifier: ReceiptNotifier,
    coupons: CouponBook,
) -> str:
    """Checks out the order and returns the receipt id of the payment."""
    _validate_items(order.items)
    total = _total_cents(order, customer, coupons)
    _reserve_stock(order, inventory)
    receipt_id = _charge(order, customer, inventory, gateway, total)
    _mark_paid(order, inventory, coupons, total)
    _send_receipt(order, customer, notifier, receipt_id)
    return receipt_id


def _validate_items(items: list[Item]) -> None:
    if not items:
        raise OrderRejected("order has no items")
    for item in items:
        if item.quantity <= 0:
            raise OrderRejected(f"invalid quantity for {item.sku}")


def _total_cents(order: Order, customer: Customer, coupons: CouponBook) -> int:
    subtotal = sum(_line_cents(item) for item in order.items)
    tax = _tax_cents(order.items, tax_rate(customer.country))
    discount = _coupon_discount_cents(order.coupon, subtotal, coupons)
    if customer.vip:
        discount += (subtotal - discount) * VIP_DISCOUNT_PERCENT // 100
    discounted = subtotal - discount
    return discounted + tax + _shipping_cents(discounted)


def _line_cents(item: Item) -> int:
    return item.unit_price_cents * item.quantity


def _tax_cents(items: list[Item], rate: Decimal) -> int:
    # Tax is rounded per line, as the accounting export expects, and is charged on the undiscounted line price.
    return sum(
        int((Decimal(_line_cents(item)) * rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP)) for item in items
    )


def _coupon_discount_cents(coupon: str | None, subtotal: int, coupons: CouponBook) -> int:
    if coupon is None:
        return 0
    percent = coupons.discount_percent(coupon)
    if percent is None:
        raise OrderRejected(f"invalid coupon: {coupon}")
    return subtotal * percent // 100


def _shipping_cents(discounted_subtotal: int) -> int:
    return 0 if discounted_subtotal >= FREE_SHIPPING_FROM_CENTS else SHIPPING_CENTS


def _reserve_stock(order: Order, inventory: Inventory) -> None:
    reserved: list[Item] = []
    try:
        for item in order.items:
            inventory.reserve(item.sku, item.quantity)
            reserved.append(item)
    except OutOfStock as error:
        _release_stock(reserved, inventory)
        order.status = "rejected"
        raise OrderRejected(f"out of stock: {error.sku}") from error


def _charge(order: Order, customer: Customer, inventory: Inventory, gateway: PaymentGateway, total: int) -> str:
    try:
        return gateway.charge(customer.email, total)
    except PaymentDeclined as error:
        _release_stock(order.items, inventory)
        order.status = "payment_failed"
        raise OrderRejected(f"payment declined: {error}") from error


def _release_stock(items: list[Item], inventory: Inventory) -> None:
    for item in items:
        inventory.release(item.sku, item.quantity)


def _mark_paid(order: Order, inventory: Inventory, coupons: CouponBook, total: int) -> None:
    for item in order.items:
        inventory.commit(item.sku, item.quantity)
    if order.coupon is not None:
        coupons.redeem(order.coupon)
    order.status = "paid"
    order.total_cents = total
    logger.info("order %s paid: %s cents", order.id, total)


def _send_receipt(order: Order, customer: Customer, notifier: ReceiptNotifier, receipt_id: str) -> None:
    try:
        notifier.send_receipt(customer.email, order.id, receipt_id)
    except Exception:
        # A missing receipt must never undo a successful payment.
        logger.warning("receipt for order %s could not be sent", order.id, exc_info=True)


'''
source = source[:start] + new + source[end:]
source = source.replace("from shop.models import Customer, Order", "from shop.models import Customer, Item, Order")
path.write_text(source)
EOF
